add(13,'diagnostiek',['MD-grens 1,980 + 3 × 3,977 = 13,911; maximum 24,878. Gevallen 11, 24 en 43 zijn potentiële uitbijters in x.','MD-grens 1,980 + 2 × 3,977 = 9,934; alleen de gevallen 24 en 43 vallen erboven.','De x-grens is ±2; alleen de gevallen 6 en 20 zijn uitbijters in x.','Het maximum 24,878 ligt onder de grens, dus er zijn geen signalen.'],'Beoordeel uitbijters in x met de Mahalanobis-afstanden.','x')
add(13,'diagnostiek',['Bij n ≤ 100 geldt ±2. Maximum 2,902 valt erbuiten; gevallen 6 en 20 zijn potentiële uitbijters in y.','Bij n ≤ 100 geldt ±3, dus er zijn geen uitbijters in y.','Omdat −1,981 boven −2 ligt, zijn er ook aan de bovenkant geen uitbijters.','Gevallen 24 en 43 zijn uitbijters in y, omdat hun gegevens gemanipuleerd zijn.'],'Beoordeel uitbijters in y met de gestandaardiseerde residuen.','y')
add(13,'diagnostiek',['Verwijder 24 en 43 om de gemelde manipulatie. Bij 6 en 20 is niets bekend: handhaven.','Verwijder 6, 11, 20, 24 en 43, want alle signalen moeten weg.','Handhaaf alle vijf de waarnemingen, ook 24 en 43.','Verwijder 6 en 20 en handhaaf 24 en 43.'],'Welke remedie past bij de uitbijters, gezien wat over de gegevens bekend is?','remedie')
