add(15,'diagnostiek toetsen',['H₀: de residuen zijn normaal verdeeld. n = 94 > 50, dus KS: Sig = 0,200 > 0,10. H₀ niet verwerpen.','H₀: de residuen zijn normaal verdeeld. n = 94, dus Shapiro-Wilk: Sig = 0,165 < 0,10. H₀ verwerpen.','H₀: potential is normaal verdeeld. Sig = 0,200, dus normaliteit is bewezen.','H₀: de residuen zijn niet normaal verdeeld. Sig = 0,200 > 0,10, dus er is een probleem.'],'Voer de analyse op normaliteit uit met α = 0,10.','normaal')
